@pytest.mark.parametrize("auth_key", ["valid_key", "invalid_key", None])
def test_authentication(api_client, auth_key, config):
    """
    Test authentication scenarios for the `/user/{username}` endpoint.
    """
    username = "testUser"
    endpoint = f"user/{username}"
    data = {
        "id": 20,
        "username": username,
        "firstName": "Alice",
        "lastName": "Smith",
        "email": "alice.smith@email.com",
        "password": "password123",
        "phone": "67890",
        "userStatus": 1,
    }

    # Set auth header based on test case
    headers = {}
    if auth_key == "valid_key":
        headers["Authorization"] = f"Bearer {config['auth']['petstore_auth']}"
    elif auth_key == "invalid_key":
        headers["Authorization"] = "Bearer invalid_token"

    # Make API call
    response = api_client.put(endpoint, data=data, headers=headers)

    # Validate the response schema
    if auth_key == "valid_key":
        assert response.status_code == 200, "Expected successful authentication"
    elif auth_key == "invalid_key":
        assert response.status_code == 401, "Expected unauthorized status"
    else:
        assert response.status_code == 401, "Expected unauthorized status due to missing auth"

    # Validate response schema
    response_status_code = str(response.status_code)
    validation_result = validator.validate_schema_by_response(endpoint, "put", response_status_code, response)
    assert validation_result["valid"], f"Schema validation error: {validation_result.get('message')}"
